schema_ddl:
CREATE TABLE operazioni (
    id INT PRIMARY KEY,
    importo NUMERIC(12,2) NOT NULL CHECK (importo > 0),
    data_operazione DATE NOT NULL,
    tipo_operazione TEXT NOT NULL CHECK (tipo_operazione IN ('bonifico', 'investimento'))
);

CREATE TABLE bonifici (
    id INT PRIMARY KEY REFERENCES operazioni(id) ON DELETE CASCADE,
    iban_destinatario TEXT NOT NULL,
    nome_beneficiario TEXT NOT NULL,
    causale TEXT
);

CREATE TABLE investimenti (
    id INT PRIMARY KEY REFERENCES operazioni(id) ON DELETE CASCADE,
    strumento_finanziario TEXT NOT NULL,
    quantita NUMERIC(14,4) NOT NULL CHECK (quantita > 0),
    prezzo_unitario NUMERIC(12,4) NOT NULL CHECK (prezzo_unitario >= 0)
);
